export enum PlayerCategory {
  Batsman = "Batsman",
  Bowler = "Bowler",
  AllRounder = "All-Rounder",
  Wicketkeeper = "Wicketkeeper",
}

export interface PlayerRole {
    id?: string;
    name: string;
    basePrice: number; // Default base price for this role
}

export interface Player {
  id: number | string;
  name: string;
  photoUrl: string;
  category: string; // Auction Category (Group: MVP, Set 1, Uncapped)
  role: string;     // Player Type (Skill: Batsman, Bowler)
  basePrice: number;
  nationality: string;
  speciality: string; // Kept for backward compat, usually same as role
  stats: {
    matches: number;
    runs: number;
    wickets: number;
  };
  status?: 'SOLD' | 'UNSOLD';
  soldPrice?: number;
  soldTo?: string;
}

export interface RegisteredPlayer {
    id: string;
    fullName: string;
    mobile: string;
    playerType: string;
    gender: string;
    dob: string;
    profilePic: string;
    paymentScreenshot: string;
    status: 'PENDING' | 'APPROVED' | 'REJECTED';
    submittedAt: number;
    [key: string]: any; // For custom fields
}

export interface Team {
  id: number | string;
  name: string;
  shortName?: string;
  owner: string;
  logoUrl: string;
  budget: number;
  players: Player[];
  minPlayers?: number;
  maxPlayers?: number;
  password?: string; // Added password for team login
}

export interface Bid {
  teamId: number | string;
  amount: number;
}

export enum AuctionStatus {
  NotStarted = "NOT_STARTED",
  InProgress = "IN_PROGRESS",
  Paused = "PAUSED",
  Sold = "SOLD",
  Unsold = "UNSOLD",
  Finished = "FINISHED",
}

export interface AuctionLog {
  message: string;
  timestamp: number;
  type: 'SYSTEM' | 'BID' | 'SOLD' | 'UNSOLD';
}

export interface BidIncrementSlab {
    from: number;
    increment: number;
}

export interface AuctionCategory {
    id?: string;
    name: string;
    basePrice: number;
    minPerTeam: number;
    maxPerTeam: number;
    bidIncrement: number;
    bidLimit: number;
    slabs: BidIncrementSlab[];
}

export interface Sponsor {
    id: string;
    name: string;
    imageUrl: string;
}

export interface SponsorConfig {
    showOnOBS: boolean;
    showOnProjector: boolean;
    loopInterval: number; // seconds
}

export type ProjectorLayout = 'STANDARD' | 'IPL' | 'MODERN';
export type OBSLayout = 'STANDARD' | 'MINIMAL' | 'VERTICAL';

export type AdminViewType = 'SQUAD' | 'PURSES' | 'UNSOLD' | 'SOLD' | 'TOP_BUY' | 'TOP_5' | 'NONE';

export interface AdminViewOverride {
    type: AdminViewType;
    data?: any; // e.g. { teamId: '...' }
}

export type BiddingStatus = 'ON' | 'PAUSED' | 'HIDDEN';

export interface AuctionState {
  players: Player[];
  teams: Team[];
  unsoldPlayers: Player[]; // This is the pool of available players
  categories: AuctionCategory[]; // Available categories with rules
  roles: PlayerRole[]; // Added Roles to State
  status: AuctionStatus;
  currentPlayerId: string | number | null; // Source of truth for current player
  currentPlayerIndex: number | null; // Derived helper
  currentBid: number | null;
  highestBidder: Team | null;
  timer: number;
  bidIncrement: number; // Global fallback increment
  bidSlabs?: BidIncrementSlab[]; // Global fallback slabs
  auctionLog: AuctionLog[];
  biddingStatus: BiddingStatus; // Replaces biddingEnabled
  playerSelectionMode: 'MANUAL' | 'AUTO';
  auctionLogoUrl?: string;
  tournamentName?: string;
  sponsors: Sponsor[];
  sponsorConfig: SponsorConfig;
  projectorLayout: ProjectorLayout;
  obsLayout: OBSLayout;
  adminViewOverride: AdminViewOverride | null;
}

export enum UserRole {
  SUPER_ADMIN = 'SUPER_ADMIN',
  ADMIN = 'ADMIN',
  TEAM_OWNER = 'TEAM_OWNER',
  VIEWER = 'VIEWER'
}

export interface UserProfile {
  uid: string;
  email: string;
  name?: string;
  role: UserRole;
  teamId?: number | string; // If role is TEAM_OWNER
}

export type FieldType = 'text' | 'number' | 'email' | 'select' | 'date' | 'file' | 'textarea';

export interface FormField {
    id: string;
    label: string;
    type: FieldType;
    required: boolean;
    options?: string[]; // For select inputs
    placeholder?: string;
}

export interface RegistrationConfig {
    isEnabled: boolean;
    fee: number;
    upiId: string;
    upiName: string;
    qrCodeUrl: string;
    terms: string;
    bannerUrl?: string; // Optional tournament logo
    customFields: FormField[];
}

export interface AuctionSetup {
    id?: string;
    title: string;
    sport: string;
    date: string;
    plan: string;
    totalTeams: number;
    purseValue: number;
    basePrice: number;
    bidIncrement: number;
    slabs?: BidIncrementSlab[]; // Global slabs for auction
    playersPerTeam: number;
    status: 'DRAFT' | 'LIVE' | 'COMPLETED';
    createdAt: number;
    createdBy?: string;
    registrationConfig?: RegistrationConfig;
    logoUrl?: string;
    bannerUrl?: string;
    playerSelectionMode?: 'MANUAL' | 'AUTO';
    sponsors?: Sponsor[];
    sponsorConfig?: SponsorConfig;
    projectorLayout?: ProjectorLayout;
    obsLayout?: OBSLayout;
}

export interface Tournament {
    id?: string;
    name: string;
    createdAt: number;
    createdBy: string;
    teams?: Team[]; // For simplicity in standalone tournaments, teams might be nested or subcollection
}

export interface AuctionContextType {
    state: AuctionState;
    userProfile: UserProfile | null;
    setUserProfile: (profile: UserProfile) => void;
    placeBid: (teamId: number | string, amount: number) => Promise<void>;
    sellPlayer: (teamId?: string | number, customPrice?: number) => Promise<void>;
    passPlayer: () => Promise<void>;
    correctPlayerSale: (playerId: string, newTeamId: string | null, newPrice: number) => Promise<void>;
    startAuction: (specificPlayerId?: string | number) => Promise<boolean>;
    endAuction: () => Promise<void>;
    resetAuction: () => Promise<void>;
    resetCurrentPlayer: () => Promise<void>;
    resetUnsoldPlayers: () => Promise<void>;
    updateBiddingStatus: (status: BiddingStatus) => Promise<void>; // Updated from toggleBidding
    toggleSelectionMode: () => Promise<void>; // Toggle Auto/Manual
    updateTheme: (type: 'PROJECTOR' | 'OBS', layout: string) => Promise<void>;
    setAdminView: (view: AdminViewOverride | null) => Promise<void>;
    logout: () => void;
    error: string | null;
    joinAuction: (id: string) => void;
    activeAuctionId: string | null;
    nextBid: number; 
}

// --- SCORING TYPES ---

export interface BatsmanStats {
    playerId: string;
    name: string;
    runs: number;
    balls: number;
    fours: number;
    sixes: number;
    isStriker: boolean;
    outBy?: string; // If out, how/who
}

export interface BowlerStats {
    playerId: string;
    name: string;
    overs: number; // 1.2
    ballsBowled: number; // actual valid balls in current over
    runsConceded: number;
    wickets: number;
    maidens: number;
}

export interface BallEvent {
    ballNumber: number;
    overNumber: number; // 0, 1, 2...
    bowlerId: string;
    batsmanId: string;
    runs: number;
    isWide: boolean;
    isNoBall: boolean;
    isWicket: boolean;
    wicketType?: string;
    extras: number;
    commentary?: string;
}

export interface InningsState {
    battingTeamId: string;
    bowlingTeamId: string;
    totalRuns: number;
    wickets: number;
    overs: number; // e.g., 10.4
    ballsInCurrentOver: number; // 0-6 (valid balls)
    currentRunRate: number;
    extras: {
        wides: number;
        noBalls: number;
        byes: number;
        legByes: number;
    };
    strikerId: string | null;
    nonStrikerId: string | null;
    currentBowlerId: string | null;
    batsmen: { [playerId: string]: BatsmanStats };
    bowlers: { [playerId: string]: BowlerStats };
    recentBalls: BallEvent[];
}

export interface Match {
    id: string;
    auctionId: string; // ID of the Auction OR the Tournament
    sourceType?: 'AUCTION' | 'TOURNAMENT'; // Distinguish between sources
    teamAId: string;
    teamBId: string;
    teamAName: string;
    teamBName: string;
    totalOvers: number;
    status: 'SCHEDULED' | 'TOSS' | 'LIVE' | 'COMPLETED';
    tossWinnerId?: string;
    tossChoice?: 'BAT' | 'BOWL';
    currentInnings: 1 | 2;
    innings: {
        1: InningsState;
        2: InningsState;
    };
    winnerId?: string;
    createdAt: number;
}

import React, { useState, useEffect, useRef } from 'react';
import { db } from '../firebase';
import { Tournament, Team, Player } from '../types';
import { Plus, Trash2, Save, FileSpreadsheet, Loader2, ChevronDown, ChevronRight, UserPlus, Users } from 'lucide-react';
import * as XLSX from 'xlsx';
import { useAuction } from '../hooks/useAuction';

const TournamentManager: React.FC = () => {
    const { userProfile } = useAuction();
    const [tournaments, setTournaments] = useState<Tournament[]>([]);
    const [loading, setLoading] = useState(true);
    const [newTournName, setNewTournName] = useState('');
    const [isCreating, setIsCreating] = useState(false);

    // Expanded Tournament ID for accordion view
    const [expandedTournId, setExpandedTournId] = useState<string | null>(null);
    const [teams, setTeams] = useState<Team[]>([]);
    const [loadingTeams, setLoadingTeams] = useState(false);

    // New Team Input
    const [newTeamName, setNewTeamName] = useState('');

    // Excel Import
    const excelInputRef = useRef<HTMLInputElement>(null);
    const [importingTeamId, setImportingTeamId] = useState<string | null>(null);

    useEffect(() => {
        if (!userProfile?.uid) return;
        const unsub = db.collection('tournaments')
            .where('createdBy', '==', userProfile.uid)
            .orderBy('createdAt', 'desc')
            .onSnapshot(snap => {
                setTournaments(snap.docs.map(d => ({ id: d.id, ...d.data() } as Tournament)));
                setLoading(false);
            });
        return () => unsub();
    }, [userProfile]);

    useEffect(() => {
        if (!expandedTournId) {
            setTeams([]);
            return;
        }
        setLoadingTeams(true);
        const unsub = db.collection('tournaments').doc(expandedTournId).collection('teams').onSnapshot(snap => {
            setTeams(snap.docs.map(d => ({ id: d.id, ...d.data() } as Team)));
            setLoadingTeams(false);
        });
        return () => unsub();
    }, [expandedTournId]);

    const handleCreateTournament = async () => {
        if (!newTournName.trim()) return;
        setIsCreating(true);
        try {
            await db.collection('tournaments').add({
                name: newTournName,
                createdBy: userProfile?.uid,
                createdAt: Date.now()
            });
            setNewTournName('');
        } catch (e) {
            console.error(e);
            alert("Failed to create tournament");
        } finally {
            setIsCreating(false);
        }
    };

    const handleDeleteTournament = async (id: string) => {
        if (window.confirm("Delete this tournament and all its teams?")) {
            await db.collection('tournaments').doc(id).delete();
        }
    };

    const handleAddTeam = async () => {
        if (!expandedTournId || !newTeamName.trim()) return;
        try {
            const teamId = db.collection('dummy').doc().id;
            await db.collection('tournaments').doc(expandedTournId).collection('teams').doc(teamId).set({
                id: teamId,
                name: newTeamName,
                owner: 'Manager',
                budget: 0,
                players: [],
                logoUrl: ''
            });
            setNewTeamName('');
        } catch (e) {
            alert("Error adding team");
        }
    };

    const handleDeleteTeam = async (teamId: string) => {
        if (!expandedTournId) return;
        if(window.confirm("Delete team?")) {
            await db.collection('tournaments').doc(expandedTournId).collection('teams').doc(teamId).delete();
        }
    };

    const handleExcelImport = async (e: React.ChangeEvent<HTMLInputElement>) => {
        const file = e.target.files?.[0];
        if (!file || !expandedTournId || !importingTeamId) return;

        try {
            const data = await file.arrayBuffer();
            const workbook = XLSX.read(data);
            const worksheet = workbook.Sheets[workbook.SheetNames[0]];
            const jsonData = XLSX.utils.sheet_to_json(worksheet);

            if (jsonData.length === 0) {
                alert("File empty");
                return;
            }

            const newPlayers: Player[] = jsonData.map((row: any) => ({
                id: db.collection('dummy').doc().id,
                name: row['Name'] || row['name'] || 'Unknown',
                role: row['Role'] || row['role'] || 'General',
                category: 'Standard',
                basePrice: 0,
                photoUrl: '',
                nationality: 'India',
                speciality: row['Role'] || 'General',
                stats: { matches: 0, runs: 0, wickets: 0 },
                status: 'SOLD',
                soldPrice: 0
            }));

            // Fetch current team to append
            const teamRef = db.collection('tournaments').doc(expandedTournId).collection('teams').doc(importingTeamId);
            const teamDoc = await teamRef.get();
            if (teamDoc.exists) {
                const currentPlayers = (teamDoc.data() as Team).players || [];
                await teamRef.update({
                    players: [...currentPlayers, ...newPlayers]
                });
                alert(`Added ${newPlayers.length} players to team.`);
            }
        } catch (err: any) {
            alert("Import Failed: " + err.message);
        } finally {
            if (excelInputRef.current) excelInputRef.current.value = '';
            setImportingTeamId(null);
        }
    };

    const triggerImport = (teamId: string) => {
        setImportingTeamId(teamId);
        setTimeout(() => excelInputRef.current?.click(), 100);
    };

    return (
        <div className="bg-white rounded-lg shadow-sm border border-gray-200 p-6">
            <h2 className="text-xl font-bold text-gray-800 mb-4 flex items-center">
                <Users className="w-5 h-5 mr-2 text-blue-600"/> Tournament Manager
            </h2>

            <div className="flex gap-2 mb-6">
                <input 
                    type="text" 
                    placeholder="New Tournament Name" 
                    className="flex-1 border rounded px-3 py-2 text-sm"
                    value={newTournName}
                    onChange={(e) => setNewTournName(e.target.value)}
                />
                <button 
                    onClick={handleCreateTournament} 
                    disabled={isCreating}
                    className="bg-blue-600 text-white px-4 py-2 rounded text-sm font-bold flex items-center"
                >
                    {isCreating ? <Loader2 className="w-4 h-4 animate-spin"/> : <Plus className="w-4 h-4 mr-1"/>} Create
                </button>
            </div>

            <div className="space-y-3">
                {tournaments.length === 0 && !loading && (
                    <div className="text-center text-gray-500 py-4 italic">No standalone tournaments created.</div>
                )}
                {tournaments.map(tourn => (
                    <div key={tourn.id} className="border border-gray-200 rounded-lg overflow-hidden">
                        <div 
                            className="bg-gray-50 p-3 flex justify-between items-center cursor-pointer hover:bg-gray-100"
                            onClick={() => setExpandedTournId(expandedTournId === tourn.id ? null : tourn.id!)}
                        >
                            <div className="flex items-center gap-2 font-bold text-gray-700">
                                {expandedTournId === tourn.id ? <ChevronDown className="w-4 h-4"/> : <ChevronRight className="w-4 h-4"/>}
                                {tourn.name}
                            </div>
                            <button 
                                onClick={(e) => { e.stopPropagation(); handleDeleteTournament(tourn.id!); }}
                                className="text-red-400 hover:text-red-600 p-1"
                            >
                                <Trash2 className="w-4 h-4"/>
                            </button>
                        </div>

                        {expandedTournId === tourn.id && (
                            <div className="p-4 bg-white border-t border-gray-200 animate-slide-up">
                                <div className="flex gap-2 mb-4">
                                    <input 
                                        type="text" 
                                        placeholder="Add Team Name" 
                                        className="flex-1 border rounded px-3 py-1.5 text-sm"
                                        value={newTeamName}
                                        onChange={(e) => setNewTeamName(e.target.value)}
                                    />
                                    <button 
                                        onClick={handleAddTeam}
                                        className="bg-green-600 text-white px-3 py-1.5 rounded text-xs font-bold"
                                    >
                                        Add Team
                                    </button>
                                </div>

                                {loadingTeams ? (
                                    <div className="flex justify-center py-4"><Loader2 className="w-5 h-5 animate-spin text-blue-500"/></div>
                                ) : (
                                    <div className="space-y-2">
                                        {teams.length === 0 && <p className="text-xs text-gray-400 text-center">No teams added yet.</p>}
                                        {teams.map(team => (
                                            <div key={team.id} className="flex justify-between items-center bg-gray-50 p-2 rounded border border-gray-100">
                                                <div>
                                                    <span className="font-bold text-sm text-gray-800">{team.name}</span>
                                                    <span className="text-xs text-gray-500 ml-2">({team.players.length} players)</span>
                                                </div>
                                                <div className="flex items-center gap-2">
                                                    <button 
                                                        onClick={() => triggerImport(team.id.toString())}
                                                        className="bg-blue-50 text-blue-600 hover:bg-blue-100 px-2 py-1 rounded text-xs flex items-center border border-blue-200"
                                                        title="Import Players from Excel"
                                                    >
                                                        <FileSpreadsheet className="w-3 h-3 mr-1"/> Import
                                                    </button>
                                                    <button onClick={() => handleDeleteTeam(team.id.toString())} className="text-gray-400 hover:text-red-500">
                                                        <Trash2 className="w-4 h-4"/>
                                                    </button>
                                                </div>
                                            </div>
                                        ))}
                                    </div>
                                )}
                            </div>
                        )}
                    </div>
                ))}
            </div>

            {/* Hidden Input for Excel */}
            <input ref={excelInputRef} type="file" accept=".xlsx, .xls" className="hidden" onChange={handleExcelImport}/>
        </div>
    );
};

export default TournamentManager;

import React, { useEffect, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { db } from '../firebase';
import { AuctionSetup, Match, Team, Tournament } from '../types';
import { ArrowLeft, Plus, Calendar, Play, Monitor, Trash2, Loader2, Trophy, Layers, PenTool, Save } from 'lucide-react';
import { useAuction } from '../hooks/useAuction';
import TournamentManager from '../components/TournamentManager';

const ScoringDashboard: React.FC = () => {
    const navigate = useNavigate();
    const { userProfile } = useAuction();
    const [matches, setMatches] = useState<Match[]>([]);
    const [loading, setLoading] = useState(true);

    // UI Tabs
    const [activeTab, setActiveTab] = useState<'MATCHES' | 'TOURNAMENTS'>('MATCHES');

    // Inline Create Match State
    const [sourceType, setSourceType] = useState<'AUCTION' | 'TOURNAMENT'>('AUCTION');
    const [sourceList, setSourceList] = useState<(AuctionSetup | Tournament)[]>([]);
    const [selectedSourceId, setSelectedSourceId] = useState('');
    const [availableTeams, setAvailableTeams] = useState<Team[]>([]);

    const [teamA, setTeamA] = useState('');
    const [teamB, setTeamB] = useState('');
    const [overs, setOvers] = useState(20);
    const [creating, setCreating] = useState(false);

    useEffect(() => {
        if (!userProfile?.uid) return;

        setLoading(true);
        // Fetch Matches
        const unsubMatches = db.collection('matches')
            .orderBy('createdAt', 'desc')
            .onSnapshot(snap => {
                setMatches(snap.docs.map(d => ({ id: d.id, ...d.data() } as Match)));
                setLoading(false);
            });
        return () => unsubMatches();
    }, [userProfile]);

    // Load Sources based on Type selection
    useEffect(() => {
        if (!userProfile?.uid) return;
        setSourceList([]);
        setSelectedSourceId('');
        setAvailableTeams([]);

        const collection = sourceType === 'AUCTION' ? 'auctions' : 'tournaments';

        db.collection(collection)
            .where('createdBy', '==', userProfile.uid)
            .get()
            .then(snap => {
                const list = snap.docs.map(d => ({ id: d.id, name: (d.data().title || d.data().name), ...d.data() } as any));
                setSourceList(list);
            });
    }, [sourceType, userProfile]);

    // Load Teams when source selected
    useEffect(() => {
        if (!selectedSourceId) {
            setAvailableTeams([]);
            return;
        }
        const collection = sourceType === 'AUCTION' ? 'auctions' : 'tournaments';
        db.collection(collection).doc(selectedSourceId).collection('teams').get()
            .then(snap => {
                setAvailableTeams(snap.docs.map(d => ({ id: d.id, ...d.data() } as Team)));
            });
    }, [selectedSourceId, sourceType]);

    const handleCreateMatch = async () => {
        if (!selectedSourceId || !teamA || !teamB || !overs) {
            alert("Please fill all fields");
            return;
        }
        if (teamA === teamB) {
            alert("Teams must be different");
            return;
        }

        setCreating(true);
        try {
            const teamAObj = availableTeams.find(t => t.id === teamA);
            const teamBObj = availableTeams.find(t => t.id === teamB);

            const newMatch: Omit<Match, 'id'> = {
                auctionId: selectedSourceId, // Used as generic source ID
                sourceType: sourceType, // NEW FIELD
                teamAId: teamA,
                teamBId: teamB,
                teamAName: teamAObj?.name || 'Team A',
                teamBName: teamBObj?.name || 'Team B',
                totalOvers: overs,
                status: 'SCHEDULED',
                currentInnings: 1,
                createdAt: Date.now(),
                innings: {
                    1: { battingTeamId: '', bowlingTeamId: '', totalRuns: 0, wickets: 0, overs: 0, ballsInCurrentOver: 0, currentRunRate: 0, extras: { wides: 0, noBalls: 0, byes: 0, legByes: 0 }, strikerId: null, nonStrikerId: null, currentBowlerId: null, batsmen: {}, bowlers: {}, recentBalls: [] },
                    2: { battingTeamId: '', bowlingTeamId: '', totalRuns: 0, wickets: 0, overs: 0, ballsInCurrentOver: 0, currentRunRate: 0, extras: { wides: 0, noBalls: 0, byes: 0, legByes: 0 }, strikerId: null, nonStrikerId: null, currentBowlerId: null, batsmen: {}, bowlers: {}, recentBalls: [] }
                }
            };

            await db.collection('matches').add(newMatch);
            setCreating(false);
            setTeamA(''); setTeamB(''); // Reset teams but keep source for fast creation
        } catch (e: any) {
            alert("Error creating match: " + e.message);
            setCreating(false);
        }
    };

    const deleteMatch = async (id: string) => {
        if(window.confirm("Delete this match?")) {
            await db.collection('matches').doc(id).delete();
        }
    };

    return (
        <div className="min-h-screen bg-gray-50 font-sans text-gray-800">
            {/* Header */}
            <header className="bg-white shadow-sm border-b border-gray-200 sticky top-0 z-20">
                <div className="container mx-auto px-4 py-3 flex justify-between items-center">
                    <div className="flex items-center gap-3">
                        <button onClick={() => navigate('/admin')} className="text-gray-400 hover:text-gray-700">
                            <ArrowLeft className="w-5 h-5"/>
                        </button>
                        <h1 className="text-lg font-bold text-gray-700 flex items-center gap-2">
                           <Trophy className="w-5 h-5 text-yellow-500"/> Cricket Scoring
                        </h1>
                    </div>

                    <div className="flex bg-gray-100 rounded-lg p-1">
                        <button 
                            onClick={() => setActiveTab('MATCHES')}
                            className={`px-4 py-1.5 rounded-md text-sm font-bold transition-all ${activeTab === 'MATCHES' ? 'bg-white shadow text-blue-600' : 'text-gray-500 hover:text-gray-700'}`}
                        >
                            Matches
                        </button>
                        <button 
                            onClick={() => setActiveTab('TOURNAMENTS')}
                            className={`px-4 py-1.5 rounded-md text-sm font-bold transition-all ${activeTab === 'TOURNAMENTS' ? 'bg-white shadow text-blue-600' : 'text-gray-500 hover:text-gray-700'}`}
                        >
                            Tournaments
                        </button>
                    </div>
                </div>
            </header>

            <main className="container mx-auto px-4 py-6 max-w-6xl">

                {activeTab === 'TOURNAMENTS' ? (
                    <TournamentManager />
                ) : (
                    <>
                        {/* INLINE CREATE MATCH PANEL */}
