                        ) : matches.length === 0 ? (
                            <div className="text-center p-12 text-gray-400 bg-white rounded-xl shadow-sm border border-dashed border-gray-300">
                                <Calendar className="w-12 h-12 mx-auto mb-3 opacity-20"/>
