                        {/* Batsman 1 */}
                        <div className="flex-1 flex items-center px-4 border-r border-white/10 h-full relative">
                            <div className={`flex flex-col ${currentInnings.strikerId ? 'opacity-100' : 'opacity-40'}`}>
