      }));
  };
  const removeOption = (fieldId: string, optionIndex: number) => {
      setRegConfig(prev => ({
          ...prev,
          customFields: prev.customFields.map(f => {
              if (f.id === fieldId && f.options) return { ...f, options: f.options.filter((_, i) => i !== optionIndex) };
